package za.ac.cput.controller; import org.springframework.web.bind.annotation.*; import za.ac.cput.domain.Notification; import za.ac.cput.service.NotificationService; import java.util.List; @RestController @RequestMapping("/notification") public class NotificationController{private final NotificationService service; public NotificationController(NotificationService service){this.service=service;} @PostMapping("/create") public Notification create(@RequestBody Notification x){return service.create(x);} @GetMapping("/read/{id}") public Notification read(@PathVariable String id){return service.read(id);} @PutMapping("/update") public Notification update(@RequestBody Notification x){return service.update(x);} @DeleteMapping("/delete/{id}") public boolean delete(@PathVariable String id){return service.delete(id);} @GetMapping("/getAll") public List<Notification> getAll(){return service.findAll();} }